begin;
alter table public.knowledge_items add column source_method text not null default 'user'check(source_method in('user','online-source'));
alter table public.knowledge_items add column source_metadata jsonb not null default '{}'::jsonb;
alter table public.knowledge_items add column plan_day integer check(plan_day between 1 and 180);
create unique index knowledge_owner_plan_day on public.knowledge_items(user_id,kind,plan_day)where plan_day is not null;
alter table public.knowledge_daily drop constraint knowledge_daily_kind_check;
alter table public.knowledge_daily add check(kind in('hadith','ayah','dua'));
create table public.knowledge_online_catalog(
 kind text not null check(kind in('hadith','ayah','dua')),day integer not null check(day between 1 and 180),item jsonb not null,primary key(kind,day)
);
create table public.knowledge_plan_settings(
 user_id uuid primary key references auth.users(id)on delete cascade,start_date date not null check(start_date between '2000-01-01'and '2100-01-01'),
 package text not null default 'online-180-v1'check(package='online-180-v1')
);
alter table public.knowledge_online_catalog enable row level security;
alter table public.knowledge_plan_settings enable row level security;
revoke all on public.knowledge_online_catalog,public.knowledge_plan_settings from public,anon,authenticated;
grant select on public.knowledge_online_catalog,public.knowledge_plan_settings to authenticated;
create policy "Read online catalog"on public.knowledge_online_catalog for select to authenticated using(true);
create policy "Read own knowledge plan"on public.knowledge_plan_settings for select to authenticated using(user_id=(select auth.uid()));

