َلَيْهِ وَسَلَّمَ فِي المَجْلِسِ الوَاحِدِ مِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: (رَبِّ اِغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الغَفُورُ)","translation":"","reference":"Hisn al-Muslim, chapter 85, entry 1: التّرمذي وغيره وانظر صحيح التّرمذي 3/ 153 وصحيح ابن ماجة 2/ 321 ولفظه للتّرمذي","source_url":"https://github.com/asellam/HisnElMuslim/blob/872764ca013116c905f7fc9c3dc972c27cd37d4a/hisn.json","translator":"","grade":"","provenance":{"provider":"Hisn al-Muslim Arabic transcription by Abdellah SELLAM (asellam/HisnElMuslim)","revision":"872764ca013116c905f7fc9c3dc972c27cd37d4a","chapter":85,"chapter_title":"مَا يُقَالُ فِي المَجْلِسِ","entry":1,"source_reference":"التّرمذي وغيره وانظر صحيح التّرمذي 3/ 153 وصحيح ابن ماجة 2/ 321 ولفظه للتّرمذي","repetition_count":100}},{"day":83,"kind":"hadith","title":"Day 083 · Bukhari 5985 · Good Manners and Form (Al-Adab)","original_text":"حَدَّثَنِي إِبْرَاهِيمُ بْنُ الْمُنْذِرِ، حَدَّثَنَا مُحَمَّدُ بْنُ مَعْنٍ، قَالَ حَدَّثَنِي أَبِي، عَنْ سَعِيدِ بْنِ أَبِي سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏ \"‏ مَنْ سَرَّهُ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَأَنْ يُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ ‏\"‏‏.‏","translation":"","reference":"Sahih al-Bukhari 5985; book 78, hadith 16","source_url":"https://raw.githubusercontent.com/fawazahmed0/hadith-api/df57907be35291c91ad6a6691180e22ca9920784/editions/ara-bukhari/5985.json","translator":"","grade":"","provenance":{"provider":"fawazahmed0/hadith-api, Arabic Sahih al-Bukhari; classical Arabic text","revision":"df57907be35291c91ad6a6691180e22ca9920784","dataset_hadithnumber":5985,"arabicnumber":5985,"canonical_url":"https://sunnah.com/bukhari:5985"}},{"day":84,"kind":"ayah","title":"Day 084 · Al-Qaari'a 9","original_text":"فَأُمُّهُۥ هَاوِيَةٌۭ","translation":"A bereft and Hungry One will be his mother,","reference":"Quran 101:9","source_url":"https://api.alquran.cloud/v1/ayah/101:9/editions/quran-uthmani,en.pickthall","translator":"Marmaduke Pickthall, The Meaning of the Glorious Koran (1930), via Al Quran Cloud en.pickthall","grade":"","provenance":{"provider":"Al Quran Cloud; Arabic Uthmani edition / Tanzil Project (https://tanzil.net)","arabic_edition":"quran-uthmani","translation_edition":"en.pickthall","global_ayah":6166,"license_notice":"Tanzil Quran Text \n  Copyright (C) 2007-2021 Tanzil Project\n  License: Creative Commons Attribution 3.0 \n\n  This copy of the Quran text is carefully produced, highly \n  verified and continuously monitored by a group of specialists \n  in Tanzil Project.\n\n  TERMS OF USE:\n \n  - Permission is granted to copy and distribute verbatim copies \n    of this text, but CHANGING IT IS NOT ALLOWED.\n\n  - This Quran text can be used in any website or application, \n    provided that its source (Tanzil Project) is clearly indicated, \n    and a link is made to tanzil.net to enable users to keep\n    track of changes.\n\n  - This copyright notice shall be included in all verbatim copies \n    of the text, and shall be reproduced appropriately in all files \n    derived from or containing substantial portion of this text.\n\n  Please check updates at: http://tanzil.net/updates/"}},{"day":84,"kind":"dua","title":"Day 084 · كَفَّارَةُ المَجْلِسِ","original_text":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","translation":"","reference":"Hisn al-Muslim, chapter 86, entry 1: أخرجه أصحاب السّنن وانظر صحيح التّرمذي 3/ 153، وقد ثبت أنّ عائشة رضي اللّه عنها قالت: ما جلس رسول اللّه صلّى اللّه عليه وسلّم مجلسا، ولا تلى قرآنا، ولا صلّى صلاة إلّا ختم ذلك بكلمات: '...'، أخرجه النّسائي في عمل اليوم واللّيلة برقم 308، وأحمد 6/ 77 وصحّحه الدّكتور فاروق حمادة في تحقيقه لعمل اليوم واللّيلة للنّسائي ص 273","source_url":"https://github.com/asellam/HisnElMuslim/blob/872764ca013116c905f7fc9c3dc972c27cd37d4a/hisn.json","translator":"","grade":"","provenance":{"provider":"Hisn al-Muslim Arabic transcription by Abdellah SELLAM (asellam/HisnElMuslim)","revision":"872764ca013116c905f7fc9c3dc972c27cd37d4a","chapter":86,"chapter_title":"كَفَّارَةُ المَجْلِسِ","entry":1,"source_reference":"أخرجه أصحاب السّنن وانظر صحيح التّرمذي 3/ 153، وقد ثبت أنّ عائشة رضي اللّه عنها قالت: ما جلس رسول اللّه صلّى اللّه عليه وسلّم مجلسا، ولا تلى قرآنا، ولا صلّى صلاة إلّا ختم ذلك بكلمات: '...'، أخرجه النّسائي في عمل اليوم واللّيلة برقم 308، وأحمد 6/ 77 وصحّحه الدّكتور فاروق حمادة في تحقيقه لعمل اليوم واللّيلة للنّسائي ص 273","repetition_count":1}},{"day":84,"kind":"hadith","title":"Day 084 · Bukhari 6326 · Invocations","original_text":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا اللَّيْثُ، قَالَ حَدَّثَنِي يَزِيدُ، عَنْ أَبِي الْخَيْرِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ أَبِي بَكْرٍ الصِّدِّيقِ ـ رضى الله عنه ـ أَنَّهُ قَالَ لِلنَّبِيِّ صلى الله عليه وسلم عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلاَتِي‏.‏ قَالَ ‏ \"‏ قُلِ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ ‏\"‏‏.‏ وَقَالَ عَمْرٌو عَنْ يَزِيدَ، عَنْ أَبِي الْخَيْرِ، إِنَّهُ سَمِعَ عَبْدَ اللَّهِ بْنَ عَمْرٍو، قَالَ أَبُو بَكْرٍ ـ رضى الله عنه ـ لِلنَّبِيِّ صلى الله عليه وسلم‏.‏","translation":"","reference":"Sahih al-Bukhari 6326; book 80, hadith 23","source_url":"https://raw.githubusercontent.com/fawazahmed0/hadith-api/df57907be35291c91ad6a6691180e22ca9920784/editions/ara-bukhari/6326.json","translator":"","grade":"","provenance":{"provider":"fawazahmed0/hadith-api, Arabic Sahih al-Bukhari; classical Arabic text","revision":"df57907be35291c91ad6a6691180e22ca9920784","dataset_hadithnumber":6326,"arabicnumber":6326,"canonical_url":"https://sunnah.com/bukhari:6326"}},{"day":85,"kind":"ayah","title":"Day 085 · Al-Qaari'a 10","original_text":"وَمَآ أَدْرَىٰكَ مَا هِيَهْ","translation":"Ah, what will convey unto thee what she is! -","reference":"Quran 101:10","sourc