 \"‏ يَرْحَمُ اللَّهُ مُوسَى، لَقَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ ‏\"‏‏.‏","translation":"","reference":"Sahih al-Bukhari 6336; book 80, hadith 33","source_url":"https://raw.githubusercontent.com/fawazahmed0/hadith-api/df57907be35291c91ad6a6691180e22ca9920784/editions/ara-bukhari/6336.json","translator":"","grade":"","provenance":{"provider":"fawazahmed0/hadith-api, Arabic Sahih al-Bukhari; classical Arabic text","revision":"df57907be35291c91ad6a6691180e22ca9920784","dataset_hadithnumber":6336,"arabicnumber":6336,"canonical_url":"https://sunnah.com/bukhari:6336"}},{"day":127,"kind":"ayah","title":"Day 127 · Al-Alaq 9","original_text":"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","translation":"Hast thou seen him who dissuadeth","reference":"Quran 96:9","source_url":"https://api.alquran.cloud/v1/ayah/96:9/editions/quran-uthmani,en.pickthall","translator":"Marmaduke Pickthall, The Meaning of the Glorious Koran (1930), via Al Quran Cloud en.pickthall","grade":"","provenance":{"provider":"Al Quran Cloud; Arabic Uthmani edition / Tanzil Project (https://tanzil.net)","arabic_edition":"quran-uthmani","translation_edition":"en.pickthall","global_ayah":6115,"license_notice":"Tanzil Quran Text \n  Copyright (C) 2007-2021 Tanzil Project\n  License: Creative Commons Attribution 3.0 \n\n  This copy of the Quran text is carefully produced, highly \n  verified and continuously monitored by a group of specialists \n  in Tanzil Project.\n\n  TERMS OF USE:\n \n  - Permission is granted to copy and distribute verbatim copies \n    of this text, but CHANGING IT IS NOT ALLOWED.\n\n  - This Quran text can be used in any website or application, \n    provided that its source (Tanzil Project) is clearly indicated, \n    and a link is made to tanzil.net to enable users to keep\n    track of changes.\n\n  - This copyright notice shall be included in all verbatim copies \n    of the text, and shall be reproduced appropriately in all files \n    derived from or containing substantial portion of this text.\n\n  Please check updates at: http://tanzil.net/updates/"}},{"day":127,"kind":"dua","title":"Day 127 · فَضْلُ التَّسْبِيحِ وَالتَّحْمِيدِ، وَالتَّهْلِيلِ، وَالتَّكْبِيرِ","original_text":"قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: (مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ البَحْرِ)","translation":"","reference":"Hisn al-Muslim, chapter 131, entry 1: البخاري 7/ 168 ومسلم 4/ 2071، وانظر: فضل من قالها مائة مرّة إذا أصبح وإذا أمسى ص 31 من هذا الكتاب.","source_url":"https://github.com/asellam/HisnElMuslim/blob/872764ca013116c905f7fc9c3dc972c27cd37d4a/hisn.json","translator":"","grade":"","provenance":{"provider":"Hisn al-Muslim Arabic transcription by Abdellah SELLAM (asellam/HisnElMuslim)","revision":"872764ca013116c905f7fc9c3dc972c27cd37d4a","chapter":131,"chapter_title":"فَضْلُ التَّسْبِيحِ وَالتَّحْمِيدِ، وَالتَّهْلِيلِ، وَالتَّكْبِيرِ","entry":1,"source_reference":"البخاري 7/ 168 ومسلم 4/ 2071، وانظر: فضل من قالها مائة مرّة إذا أصبح وإذا أمسى ص 31 من هذا الكتاب.","repetition_count":100}},{"day":127,"kind":"hadith","title":"Day 127 · Bukhari 6434 · To make the Heart Tender (Ar-Riqaq)","original_text":"حَدَّثَنِي يَحْيَى بْنُ حَمَّادٍ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ بَيَانٍ، عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ، عَنْ مِرْدَاسٍ الأَسْلَمِيِّ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏ \"‏ يَذْهَبُ الصَّالِحُونَ الأَوَّلُ فَالأَوَّلُ، وَيَبْقَى حُفَالَةٌ كَحُفَالَةِ الشَّعِيرِ أَوِ التَّمْرِ، لاَ يُبَالِيهِمُ اللَّهُ بَالَةً ‏\"‏‏.‏ قَالَ أَبُو عَبْدِ اللَّهِ يُقَالُ حُفَالَةٌ وَحُثَالَةٌ‏.‏","translation":"","reference":"Sahih al-Bukhari 6434; book 81, hadith 23","source_url":"https://raw.githubusercontent.com/fawazahmed0/hadith-api/df57907be35291c91ad6a6691180e22ca9920784/editions/ara-bukhari/6434.json","translator":"","grade":"","provenance":{"provider":"fawazahmed0/hadith-api, Arabic Sahih al-Bukhari; classical Arabic text","revision":"df57907be35291c91ad6a6691180e22ca9920784","dataset_hadithnumber":6434,"arabicnumber":6434,"canonical_url":"https://sunnah.com/bukhari:6434"}},{"day":128,"kind":"ayah","title":"Day 128 · Al-Alaq 10","original_text":"عَبْدًا إِذَا صَلَّىٰٓ","translation":"A slave when he prayeth?","reference":"Quran 96:10","source_url":"https://api.alquran.cloud/v1/ayah/96:10/editions/quran-uthmani,en.pickthall","translator":"Marmaduke Pickthall, The Meaning of the Glorious Koran (1930), via Al Quran Cloud en.pickthall","grade":"","provenance":{"provider":"Al Quran Cloud; Arabic Uthmani edition / Tanzil Project (https://tanzil.net)","arabic_edition":"quran-uthmani","translation_edition":"en.pickthall","global_ayah":6116,"license_notice":"Tanzil Quran Text \n  Copyright (C) 2007-2021 Tanzil Project\n  License: Creative Commons Attribution 3.0 \n\n  This copy of the Quran text is carefully produced, highly \n  verified and continuously monitored by a group of specialists \n  in Tanzil Project.\n\n  TERMS OF USE:\n \n  - Permission is granted to copy and distribute verbatim copies \n    of this text, but CHANGING IT IS NOT ALLOWED.\n\n  - This Quran text can be used in any website or application, \n    provided that its source (Tanzil Project) is clearly indicated, \n    and a link is made to tanzil.net to enable users to keep\n    track of changes.\n\n  - This copyright notice shall be included in all verbatim copies \n    of the text, and shall be reproduced appropriately in all files \n    derived from or containing substantial portion of this text.\n\n  Please check updates at: http://tanzil.net/updates/"}},{"day":128,"kind":"dua","title":"Day 128 · كَيْفَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَبِّحُ؟","original_text":"عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: (رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُ التَّسْبِيحَ بِيَمِينِهِ)","translation":"","reference":"Hisn al-Muslim, chapter 132, entry 1: أخرجه أبو داود بلفظه 2/ 81 والترمذي 5/ 521 وانظر صحيح الجامع 4/ 271 برقم 4865","source_url":"https://github.com/asellam/HisnElMuslim/blob/872764ca013116c905f7fc9c3dc972c27cd37d4a/hisn.json","translator":"","grade":"","provenance":{"provider":"Hisn al-Muslim Arabic transcription by Abdellah SELLAM (asellam/HisnElMuslim)","revision":"872764ca013116c905f7fc9c3dc972c27cd37d4a","chapter":132,"chapter_title":"كَيْفَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَبِّحُ؟","entry":1,"source_reference":"أخرجه أبو داود بلفظه 2/ 81 والترمذي 5/ 521 وانظر صحيح الجامع 4/ 271 برقم 4865","repetition_count":1}},{"day":128,"kind":"hadith","title":"Day 128 · Bukhari 7398 · Oneness, Uniqueness of Allah (Tawheed)","original_text":"حَدَّثَنَا يُوسُفُ بْنُ مُوسَى، حَدَّثَنَا أَبُو خَالِدٍ الأَحْمَرُ، قَالَ سَمِعْتُ هِشَامَ بْنَ عُرْوَةَ، يُحَدِّثُ عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ قَالُوا يَا رَسُولَ اللَّهِ إِنَّ هُنَا أَقْوَامًا حَدِيثًا عَهْدُهُمْ بِشِرْكٍ، يَأْتُونَا بِلُحْمَانٍ لاَ نَدْرِي يَذْكُرُونَ اسْمَ اللَّهِ عَلَيْهَا أَمْ لاَ‏.‏ قَالَ ‏ \"‏ اذْكُرُوا أَنْتُمُ اسْمَ اللَّهِ وَكُلُوا ‏\"‏‏.‏ تَابَعَهُ مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ وَالدَّرَاوَرْدِيُّ وَأُسَامَةُ بْنُ حَفْصٍ‏.‏","translation":"","reference":"Sahih al-Bukhari 7398; book 97, hadith 27","source_url":"https://raw.githubusercontent.com/fawazahmed0/hadith-api/df57907be35291c91ad6a6691180e22ca9920784/editions/ara-bukhari/7398.json","translator":"","grade":"","provenance":{"provider":"fawazahmed0/hadith-api, Arabic Sahih al-Bukhari; classical Arabic text","revision":"df57907be35291c91ad6a6691180e22ca9920784","dataset_hadithnumber":7398,"arabicnumber":7398,"canonical_url":"https://sunnah.com/bukhari:7398"}},{"day":129,"kind":"ayah","title":"Day 129 · Al-Alaq 11","original_text":"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","translation":"Hast thou seen if he relieth on the guidance (of Allah)","reference":"Quran 96:11","source_url":"https://api.alquran.cloud/v1/ayah/96:11/editions/quran-uthmani,en.pickthall","translator":"Marmaduke Pickthall, The Meaning of the Glorious Koran (1930), via Al Quran Cloud en.pickthall","grade":"","provenance":{"provider":"Al Quran Cloud; Arabic Uthmani edition / Tanzil Project (https://tanzil.net)","arabic_edition":"quran-uthmani","translation_edition":"en.pickthall","global_ayah":6117,"license_notice":"Tanzil Quran Text \n  Copyright (C) 2007-2021 Tanzil Project\n  License: Creative Commons Attribution 3.0 \n\n  This copy of the Quran text is carefully produced, highly \n  verified and continuously monitored by a group of specialists \n  in Tanzil Project.\n\n  TERMS OF USE:\n \n  - Permission is granted to copy and distribute verbatim copies \n    of this text, but CHANGING IT IS NOT ALLOWED.\n\n  - This Quran text can be used in any website or application, \n    provided that its source (Tanzil Project) is clearly indicated, \n    and a link is made to tanzil.net to enable users to keep\n    track of changes.\n\n  - This copyright notice shall be included in all verbatim copies \n    of the text, and shall be reproduced appropriately in all files \n    derived from or containing substantial portion of this text.\n\n  Please check updates at: http://tanzil.net/updates/"}},{"day":129,"kind":"dua","title":"Day 129 · مِنْ أَنْوَاعِ الخَيْرِ وَالآدَابِ الجَامِعَةِ","original_text":"إِذَا كَانَ جُنْحُ اللَّيْلِ - أَوْ أَمْسَيْتُمْ - فَكُفُّوا صِبْيَانَكُمْ؛ فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيْلِ فَخَلُّوهُمْ، وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اِسْمَ اللَّهِ، فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا مُغْلَقًا، وَأَوْكُوا قِرَبَكُمْ وَاذْكُرُوا اِسْمَ اللَّهِ، وَخَمِّرُوا آنِيَتَكُمْ وَاذْكُرُوا اِسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئًا، وَأَطْفِئُوا مَصَابِيحَكُمْ\r\nوَصَلَّى اللَّهُ وَسَلَّمَ وَبَارَكَ عَلَى نَبِيِّنَا مُحَمَّدٍ وَعَلَى آلِهِ وَأَصْحَابِهِ أَجْمَعِينَ","translation":"","reference":"Hisn al-Muslim, chapter 133, entry 1: البخاري مع الفتح 10/ 88 ومسلم 3/ 1595","source_url":"https://github.com/asellam/HisnElMuslim/blob/872764ca013116c905f7fc9c3dc972c27cd37d4a/hisn.json","translator":"","grade":"","provenance":{"provider":"Hisn al-Muslim Arabic transcription by Abdellah SELLAM (asellam/HisnElMuslim)","revision":"872764ca013116c905f7fc9c3dc972c27cd37d4a","chapter":133,"chapter_title":"مِنْ أَنْوَاعِ الخَيْرِ وَالآدَابِ الجَامِعَةِ","entry":1,"source_reference":"البخاري مع الفتح 10/ 88 ومسلم 3/ 1595","repetition_count":1}},{"day":129,"kind":"hadith","title":"Day 129 · Bukhari 32 · Belief","original_text":"حَدَّثَنَا أَبُو الْوَلِيدِ، قَالَ حَدَّثَنَا شُعْبَةُ، ح‏.‏ قَالَ وَحَدَّثَنِي بِشْرٌ، قَالَ حَدَّثَنَا مُحَمَّدٌ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَمَّا نَزَلَتِ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ قَالَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم أَيُّنَا لَمْ يَظْلِمْ فَأَنْزَلَ اللَّهُ ‏{‏إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏}‏‏.‏","translation":"","reference":"Sahih al-Bukhari 32; book 2, hadith 25","source_url":"https://raw.githubusercontent.com/fawazahmed0/hadith-api/df57907be35291c91ad6a6691180e22ca9920784/editions/ara-bukhari/32.json","translator":"","grade":"","provenance":{"provider":"fawazahmed0/hadith-api, Arabic Sahih al-Bukhari; classical Arabic text","revision":"df57907be35291c91ad6a6691180e22ca9920784","dataset_hadithnumber":32,"arabicnumber":32,"canonical_url":"https://sunnah.com/bukhari:32"}},{"day":130,"kind":"ayah","title":"Day 130 · Al-Alaq 12","original_text":"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","translation":"Or enjoineth piety?","reference":"Quran 96:12","source_url":"https://api.alquran.cloud/v1/ayah/96:12/editions/quran-uthmani,en.pickthall","translator":"Marmaduke Pickthall, The Meaning of the Glorious Koran (1930), via Al Quran Cloud en.pickthall","grade":"","provenance":{"provider":"Al Quran Cloud; Arabic Uthmani edition / Tanzil Project (https://tanzil.net)","arabic_edition":"quran-uthmani","translation_edition":"en.pickthall","global_ayah":6118,"license_notice":"Tanzil Quran Text \n  Copyright (C) 2007-2