create function public.knowledge_plan_status()returns jsonb language plpgsql security invoker set search_path=''as $$
declare start_date date;today date:=(now()at time zone 'Asia/Dhaka')::date;begin
 if auth.uid()is null then raise exception 'Sign in first';end if;
 select s.start_date into start_date from public.knowledge_plan_settings s where user_id=auth.uid();
 return jsonb_build_object('available',(select count(*)=540 from public.knowledge_online_catalog),'installed',start_date is not null,'start_date',start_date,'day',case when start_date is null then null else today-start_date+1 end);
end$$;

create function public.install_knowledge_plan(p_start date)returns jsonb language plpgsql security definer set search_path=''as $$
declare owner_id uuid:=auth.uid();previous_start date;matching integer;today date:=(now()at time zone 'Asia/Dhaka')::date;begin
 if owner_id is null then raise exception 'Sign in first';end if;
 if p_start is null or p_start<'2000-01-01'or p_start>'2100-01-01'then raise exception 'Choose a valid plan start date';end if;
 if(select count(*)from public.knowledge_online_catalog)<>540 then raise exception 'The online collection is incomplete';end if;
 insert into public.profiles(id)values(owner_id)on conflict do nothing;
 perform 1 from public.profiles where id=owner_id for update;
 select start_date into previous_start from public.knowledge_plan_settings where user_id=owner_id;
 insert into public.knowledge_items(user_id,kind,title,original_text,translation,reference,source_url,translator,grade,reviewed_at,source_method,source_metadata,plan_day)
 select owner_id,c.kind,c.item->>'title',c.item->>'original_text',c.item->>'translation',c.item->>'reference',c.item->>'source_url',c.item->>'translator',c.item->>'grade',now(),'online-source',c.item->'provenance',c.day
 from public.knowledge_online_catalog c
 on conflict(user_id,kind,lower(trim(reference)))do update set
  source_method='online-source',source_metadata=excluded.source_metadata,plan_day=excluded.plan_day,reviewed_at=coalesce(knowledge_items.reviewed_at,excluded.reviewed_at)
 where knowledge_items.original_text=excluded.original_text and knowledge_items.translation=excluded.translation
  and knowledge_items.source_url=excluded.source_url and knowledge_items.translator=excluded.translator and knowledge_items.grade=excluded.grade;
 select count(*)into matching from public.knowledge_online_catalog c join public.knowledge_items i
 on i.user_id=owner_id and i.kind=c.kind and lower(trim(i.reference))=lower(trim(c.item->>'reference'))
 and i.original_text=c.item->>'original_text'and i.translation=c.item->>'translation'and i.source_url=c.item->>'source_url'
 and i.translator=c.item->>'translator'and i.grade=c.item->>'grade';
 if matching<>540 then raise exception 'An existing reference has different text or attribution. Your entries were preserved; resolve that reference before loading the plan';end if;
 insert into public.knowledge_plan_settings(user_id,start_date)values(owner_id,p_start)on conflict(user_id)do update set start_date=excluded.start_date;
 if previous_start is distinct from p_start then delete from public.knowledge_daily where user_id=owner_id and day=today;end if;
 return jsonb_build_object('days',180,'hadith',180,'ayah',180,'dua',180,'start_date',p_start);
end$$;

-- Editing online content returns it to personal review. Do not retain a
-- provider-match badge after any user edits.
create or replace function public.save_knowledge_item(p_item jsonb,p_id uuid default null)returns uuid
language plpgsql security definer set search_path=''as $$
declare owner_id uuid:=auth.uid();item_key uuid;begin
 if owner_id is null then raise exception 'Sign in first';end if;
 if jsonb_typeof(p_item)is distinct from 'object'then raise exception 'Provide one knowledge item';end if;
 if p_id is null then
  insert into public.knowledge_items(user_id,kind,title,original_text,translation,reference,source_url,translator,grade)
  values(owner_id,p_item->>'kind',trim(p_item->>'title'),trim(p_item->>'original_text'),coalesce(p_item->>'translation',''),trim(p_item->>'reference'),trim(p_item->>'source_url'),coalesce(p_item->>'translator',''),coalesce(p_item->>'grade',''))returning id into item_key;
 else
  if exists(select 1 from public.knowledge_items where id=p_id and user_id=owner_id and kind<>p_item->>'kind')then raise exception 'The collection type cannot be changed; add a separate item instead';end if;
  update public.knowledge_items set kind=p_item->>'kind',title=trim(p_item->>'title'),original_text=trim(p_item->>'original_text'),translation=coalesce(p_item->>'translation',''),reference=trim(p_item->>'reference'),source_url=trim(p_item->>'source_url'),translator=coalesce(p_item->>'translator',''),grade=coalesce(p_item->>'grade',''),reviewed_at=null,source_method='user'
  where id=p_id and user_id=owner_id returning id into item_key;
  if not found then raise exception 'Knowledge item not found';end if;
 end if;
 return item_key;
end$$;

create or replace function public.review_knowledge(p_id uuid,p_confirm boolean)returns void language plpgsql security definer set search_path=''as $$
begin
 if auth.uid()is null then raise exception 'Sign in first';end if;
 if p_confirm is null then raise exception 'Confirm the review state';end if;
 update public.knowledge_items set reviewed_at=case when p_confirm then now()else null end,source_method='user'where id=p_id and user_id=auth.uid()and not archived;
 if not found then raise exception 'Active knowledge item not found';end if;
end$$;

create or replace function public.knowledge_daily_items()returns jsonb language plpgsql security definer set search_path=''as $$
declare owner_id uuid:=auth.uid();today date:=(now()at time zone 'Asia/Dhaka')::date;plan_start date;day_number integer;result jsonb;begin
 if owner_id is null then raise exception 'Sign in first';end if;
 insert into public.profiles(id)values(owner_id)on conflict do nothing;
 perform 1 from public.profiles where id=owner_id for update;
 select start_date into plan_start from public.knowledge_plan_settings where user_id=owner_id;
 day_number:=today-plan_start+1;
 if plan_start is null then
  insert into public.knowledge_daily(user_id,day,kind,item_id)
  select owner_id,today,k.kind,item.id from(values('hadith'),('ayah'),('dua'))k(kind)
  cross join lateral(select id from public.knowledge_items where user_id=owner_id and kind=k.kind and reviewed_at is not null and not archived order by md5(today::text||id::text)limit 1)item
  on conflict(user_id,day,kind)do nothing;
 elsif day_number between 1 and 180 then
  insert into public.knowledge_daily(user_id,day,kind,item_id)
  select owner_id,today,i.kind,i.id from public.knowledge_items i where i.user_id=owner_id and i.plan_day=day_number and i.reviewed_at is not null and not i.archived
  on conflict(user_id,day,kind)do nothing;
 end if;
 select coalesce(jsonb_object_agg(d.kind,to_jsonb(i)),'{}'::jsonb)into result from public.knowledge_daily d join public.knowledge_items i on i.id=d.item_id
 where d.user_id=owner_id and d.day=today and i.kind=d.kind and i.reviewed_at is not null and not i.archived;
 if plan_start is not null then result:=result||jsonb_build_object('_plan',jsonb_build_object('day',day_number,'start_date',plan_start,'status',case when day_number<1 then 'upcoming'when day_number>180 then 'complete'else 'active'end));end if;
 return result;
end$$;

create or replace function public.knowledge_list(p_kind text,p_search text default '',p_status text default 'all',p_review text default 'all',p_archived boolean default false,p_page integer default 0)returns jsonb
language plpgsql security invoker set search_path=''as $$
declare result jsonb;begin
 if auth.uid()is null then raise exception 'Sign in first';end if;
 if p_kind is null or p_kind not in('hadith','ayah','dua')or p_status is null or p_status not in('all','new','learning','memorized')or p_review is null or p_review not in('all','reviewed','pending')or p_search is null or length(p_search)>200 or p_page is null or p_page<0 or p_page>100000 or p_archived is null then raise exception 'Invalid library filter';end if;
 with filtered as materialized(
  select i.*,coalesce(p.status,'new')as status from public.knowledge_items i left join public.knowledge_progress p on p.user_id=auth.uid()and p.item_id=i.id
  where i.user_id=auth.uid()and i.kind=p_kind and i.archived=p_archived
  and(p_search=''or position(lower(p_search)in lower(i.title||' '||i.original_text||' '||i.translation||' '||i.reference))>0)
  and(p_status='all'or coalesce(p.status,'new')=p_status)
  and(p_review='all'or(p_review='reviewed'and i.reviewed_at is not null)or(p_review='pending'and i.reviewed_at is null))
 ),page as(select * from filtered order by plan_day nulls last,created_at,id limit 20 offset p_page*20)
 select jsonb_build_object('total',(select count(*)from filtered),'items',(select coalesce(jsonb_agg(row_to_json(page)order by plan_day nulls last,created_at,id),'[]'::jsonb)from page))into result;
 return result;
end$$;

revoke all on function public.knowledge_plan_status(),public.install_knowledge_plan(date)from public,anon;
grant execute on function public.knowledge_plan_status(),public.install_knowledge_plan(date)to authenticated;
commit;
